#!/bin/bash
# Stops the backend and streamer agents and removes them, so they no longer
# start at login. Logs in ~/Library/Logs/liberator-stream are kept.
set -euo pipefail

DOMAIN="gui/$(id -u)"
for label in com.liberator-stream.streamer com.liberator-stream.backend; do
  plist="$HOME/Library/LaunchAgents/$label.plist"
  if launchctl print "$DOMAIN/$label" >/dev/null 2>&1; then
    launchctl bootout "$DOMAIN/$label"
    echo "Stopped $label"
  fi
  # Generated by install.sh from the template in launchd/
  rm -f "$plist"
done
